import base64
import os

SHABBY_BANK_B64 = """"""

def ensure_shabby_bank_image(target_path: str):
    if not os.path.exists(target_path):
        os.makedirs(os.path.dirname(target_path), exist_ok=True)
        with open(target_path, "wb") as f_out:
            f_out.write(base64.b64decode(SHABBY_BANK_B64))
